import 'package:flutter/material.dart'; import '../services/auth_service.dart'; import '../services/bounty_service.dart'; import '../models/app_user.dart'; import 'login_screen.dart'; import 'home_shell.dart';
class AuthGate extends StatefulWidget {const AuthGate({super.key,required this.auth,required this.bounties});final AuthService auth;final BountyService bounties;@override State<AuthGate> createState()=>_AuthGateState();}
class _AuthGateState extends State<AuthGate>{late Future<AppUser?> future;@override void initState(){super.initState();future=_restore();}Future<AppUser?> _restore()async{if(await widget.auth.storage.read()==null)return null;try{return await widget.auth.me();}catch(_){await widget.auth.storage.clear();return null;}}@override Widget build(BuildContext c)=>FutureBuilder<AppUser?>(future:future,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Scaffold(body:Center(child:CircularProgressIndicator()));return s.data==null?LoginScreen(auth:widget.auth,bounties:widget.bounties):HomeShell(auth:widget.auth,bounties:widget.bounties,user:s.data!);});}